begin isolation level repeatable read;
set local standard_conforming_strings=on;
create temporary table lolita_review_scope_guard on commit drop as
select 'books'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.books r where r.id<>'lolita') rows
union all
select 'place_references'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.place_references r where r.book_id<>'lolita') rows
union all
select 'place_descriptions'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.place_descriptions r where r.book_id<>'lolita') rows
union all
select 'sources'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.sources r where r.book_id<>'lolita') rows
union all
select 'content_translations'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.content_translations r where r.book_id<>'lolita') rows;
