update public.books set metadata=jsonb_set(metadata,'{geographicReview,coveredSettings}',coalesce(metadata->'geographicReview'->'coveredSettings','{}'::jsonb)||'{"36":{"Hobby House":"mississippi","Little Iceberg Lake":"colorado","Poplar Shade":"utah"},"57":{"Strada anonima dell’incontro con Mary":"regional-elphinstone"},"63":{"Casa degli Schiller: salotto":"regional-coalmont"}}'::jsonb) where id='lolita';
