adata->'geographicReview'->'regionalPlaces') r where r->>'id'='regional-arctic-canada');
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(b.metadata->'geographicReview'->'regionalPlaces')||'[{"id":"regional-appalachia","keys":["Appalachian Mountains"],"place":{"name":"Appalachia · unnamed town","area":"Appalachian region","coords":[38,-80],"kind":"uncertain","zoom":4,"checked":"2026-10-16","status":"Uncertain regional position","note":"Part II, chapter 30 explicitly places the night stop somewhere in Appalachia. The diamond represents the broad region, not the anonymous town, a particular state or the disguised roads.","method":"Only the geographical region is established. This rounded point is selected within it for orientation; it is not a scene, address, route reconstruction or probability estimate.","positionSource":{"url":"https://www.nps.gov/articles/series.htm?id=12C422BC-1DD8-B71B-0B1552CA902E5909","label":"Geographical region · representative point"},"narrativeSource":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=188","label":"Vladimir Nabokov · Lolita · 2.30"},"geographicReview":{"precision":"region","realWorldIdentity":"not-established"}},"sceneText":"Part II, chapter 30 explicitly places the night stop somewhere in Appalachia. The diamond represents the broad region, not the anonymous town, a particular state or the disguised roads.","categories":{},"evidenceLabel":"Original section evidence","sectionOccurrences":{"64":{"category":"action","scene":"Exhausted after the muddy detour, Humbert stops in an unnamed Appalachian town, drinks and watches its illuminated signs. Only the Appalachian region is established.","source":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=188","label":"Vladimir Nabokov · Lolita · 2.30"},"evidenceReview":"7c6bc69e19f38d7f676e13ffcfaac71e3c7e3d779da5aacd0cf278accbd5ee75"}}}]'::jsonb) where b.id='lolita' and not exists(select 1 from jsonb_array_elements(b.metadata->'geographicReview'->'regionalPlaces') r where r->>'id'='