update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(b.metadata->'geographicReview'->'regionalPlaces')||'[{"id":"scene-magnolia-gardens","keys":["Magnolia Garden"],"categories":{},"evidenceLabel":"Original section evidence","sectionOccurrences":{"36":{"category":"action","scene":"At Magnolia Garden, Dolores sits on a bench with her Sunday newspapers. Zimmer identifies the garden near Charleston; the point represents the grounds, not the bench.","source":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=102","label":"Vladimir Nabokov · Lolita · 2.2"},"evidenceReview":"d01e0e025b987e7e45f08de0050631d3db2f0b86cb1f832b86b4cb453bc35bd8"}},"sceneText":"","place":{"name":"Magnolia Garden","area":"Magnolia Plantation & Gardens · Charleston, South Carolina","coords":[32.876494099794,-80.083391601259],"kind":"area","zoom":13,"checked":"2026-10-16","status":"Representative geographical position","note":"Zimmer identifies the garden in Part II, chapter 2 as Magnolia Gardens near Charleston. The official site confirms the Ashley River grounds at 3550 Ashley River Road. The point locates the property, not Dolores’s bench.","method":"Official property address matched to Esri PointAddress; the scene is verified independently in Part II, chapter 2.","positionSource":{"url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates?SingleLine=Magnolia+Plantation+and+Gardens%2C+3550+Ashley+River+Road%2C+Charleston%2C+SC&f=json&outFields=Match_addr%2CAddr_type&maxLocations=3","label":"Esri · official property address"},"narrativeSource":{"url":"https://dezimmer.net/LolitaUSA/Trip1.htm","label":"Dieter E. Zimmer · Lolita, USA · Trip One"},"additionalSource":{"url":"https://www.magnoliaplantation.com/contact","label":"Magnolia Plantation & Gardens · official site"}}}]'::jsonb) where b.id='lolita' and not exists(select 1 from jsonb_array_elements(b.metadata->'geographicReview'->'regionalPlaces') r where r->>'id'='scene-magnolia-gardens');
