update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-elphinstone' then r||jsonb_build_object('sectionOccurrences',coalesce(r->'sectionOccurrences','{}'::jsonb)||'{"56":{"category":"action","scene":"At Elphinstone, Dolores falls ill, enters hospital and disappears. Humbert’s motel and hospital scenes are geographically placed only within the western Rockies; real-town identifications remain hypotheses.","source":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=158","label":"Vladimir Nabokov · Lolita · 2.22"},"evidenceReview":"7a277b826f853742e8a4de92067e59516255f40729fb98156daa64f9aec0056a"},"57":{"category":"action","scene":"Humbert questions the Ponderosa Lodge landlady and confronts Mary after Dolores’s disappearance. These scenes belong to the Elphinstone aftermath; the false addresses in the registers remain mentions.","source":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=164","label":"Vladimir Nabokov · Lolita · 2.23"},"evidenceReview":"a7a3988ddc4d1eed586d802ad13cccc54b28eeeecf387b53549a7efa26c6a37a"}}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata->'geographicReview'->'regionalPlaces') with ordinality as a(r,ord))) where b.id='lolita';
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-coalmont' then r||jsonb_build_object('sectionOccurrences',coalesce(r->'sectionOccurrences','{}'::jsonb)||'{"62":{"category":"action","scene":"In Coalmont, Humbert uses a telephone booth, asks for directions and reaches the Schillers’ house. The narrator explicitly camouflages the town; the broad Midwest position identifies no real Coalmont.","source":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=178","label":"Vladimir Nabokov · Lolita · 2.28"},"evidenceReview":"0774cacdf5b2b6a3059ce900ed9d0cb14178c1a131273b856f16ed376d280a29"},"63":{"category":"action","scene":"Humbert meets the pregnant Dolores at the Schillers’ home, the house reached in the preceding chapter. This is Coalmont’s present scene; Dolores’s accounts of other places are separate narrative levels.","source":{"url":"https://online.fliphtml5.com/unwsfj/Lolita---Vladimir-Nabokov/#p=180","label":"Vladimir Nabokov · Lolita · 2.29"},"evidenceReview":"09ddf12ac42917ef68b0387dba27247483dd5d146681ba8c978c5a5c1d2256cc"}}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata->'geographicReview'->'regionalPlaces') with ordinality as a(r,ord))) where b.id='lolita';
do $guard$ begin if exists(select 1 from public.books where id='lolita' and metadata->>'footerHtml' is not null and metadata->>'footerHtml'<>'<p>Critical geographical sources. Scene classifications also rely on the original chapter context.</p><p><a href="https://journals.openedition.org/ejas/7550" target="_blank" rel="noopener noreferrer">Monica Manolescu-Oancea, <em>Inventing and naming America: Place and Place Names in Vladimir Nabokov’s Lolita</em>, 2009</a>.</p><p>Dieter E. Zimmer, <em>Lolita, USA</em>: <a href="https://dezimmer.net/LolitaUSA/Trip1.htm" target="_blank" rel="noopener noreferrer">Trip One</a> · <a href="https://www.dezimmer.net/LolitaUSA/Trip2.htm" target="_blank" rel="noopener noreferrer">Trip Two</a>.</p>') then raise exception 'Existing footer changed';end if;end $guard$;
update public.books set metadata=jsonb_set(metadata,'{footerHtml}','"<p>Critical geographical sources. Scene classifications also rely on the original chapter context.</p><p><a href=\"https://journals.openedition.org/ejas/7550\" target=\"_blank\" rel=\"noopener noreferrer\">Monica Manolescu-Oancea, <em>Inventing and naming America: Place and Place Names in Vladimir Nabokov’s Lolita</em>, 2009</a>.</p><p>Dieter E. Zimmer, <em>Lolita, USA</em>: <a href=\"https://dezimmer.net/LolitaUSA/Trip1.htm\" target=\"_blank\" rel=\"noopener noreferrer\">Trip One</a> · <a href=\"https://www.dezimmer.net/LolitaUSA/Trip2.htm\" target=\"_blank\" rel=\"noopener noreferrer\">Trip Two</a>.</p>"'::jsonb) where id='lolita';
update public.place_references set category='action',scene_text='In Paris, Valeria reveals her affair. Humbert questions her in a taxi and then meets her lover at a café; the text gives no address for these scenes.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"f143278ee5a71bb08c531d5f01e33f0212852a5b76802698cba20695d760c41a","sectionId":"1.8","placeId":"paris","category":"action","narrativeLevel":"recalled scene","reason":"La rivelazione di Valeria, il taxi e il colloquio al caffè sono azioni ambientate a Parigi, non informazioni anagrafiche.","viewerPage":19,"printedPage":18,"sourceImageSha256":"b48dd8b4adb48994b432b122c67b357e10b81390c10c28587348f7da6f54bc1b","sourceSectionSha256":"74a5a48ecc9b5a8be1ae80b118c0974c4d5b314c1ae21f8f5e4c426fbcdbe790","pdfPages":[21],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='9:core:paris' and section_id=9 and place_id='paris';
update public.place_references set category='action',scene_text='A doctor’s embedded account describes Valeria and Maximovich during an experiment in California. This is the reported scene’s setting, not a visit by Humbert or an identified laboratory.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"44f4305462e1fa952375c1383336c42b3c84ba7cc548fa463589e4b0184ef41a","sectionId":"1.8","placeId":"california","category":"action","narrativeLevel":"embedded testimony","reason":"Il medico racconta ciò che ha visto nell’esperimento californiano. È una scena nel racconto intercalato, non un viaggio di Humbert.","viewerPage":20,"printedPage":19,"sourceImageSha256":"bd37ed9bdb091e765e072c25a68d3e6d7d2d2dc41cead03cf0c7199ab104de25","sourceSectionSha256":"74a5a48ecc9b5a8be1ae80b118c0974c4d5b314c1ae21f8f5e4c426fbcdbe790","pdfPages":[24],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='9:core:california' and section_id=9 and place_id='california';
update public.place_references set category='action',scene_text='Humbert tells a story set in Arles: an attack, an explosion and the assailant’s escape. The city belongs to this embedded narrative, not to Humbert’s itinerary.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"6ac3ca5ed49d5e4d9489915eb9eba1a5288ce425beee169ad7c1cc65b030bfaa","sectionId":"1.20","placeId":"arles","category":"action","narrativeLevel":"embedded story","reason":"Il racconto intercalato narra accoltellamento, esplosione e fuga ad Arles. Non è una visita di Humbert né una ricostruzione storica verificata.","viewerPage":57,"printedPage":56,"sourceImageSha256":"c972646427d72af64aab5102cc6fee969ce21cfdddef3fd2f321d16a92f5c7b2","sourceSectionSha256":"fc89233a40e0a3b0f07885207651344b5ccbcbee047670a6894bee2c111619d3","pdfPages":[75],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='21:core:arles' and section_id=21 and place_id='arles';
update public.place_references set category='action',scene_text='Humbert tells a story set in Arles: an attack, an explosion and the assailant’s escape. The city belongs to this embedded narrative, not to Humbert’s itinerary.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"5087a112a34062600d1dbbe3cd7dec7b188a78368890b0d000096a346792c984","sectionId":"1.20","placeId":"france","category":"action","narrativeLevel":"embedded story","reason":"L’ambientazione francese è esplicita nello stesso racconto di Arles, a livello intercalato.","viewerPage":57,"printedPage":56,"sourceImageSha256":"c972646427d72af64aab5102cc6fee969ce21cfdddef3fd2f321d16a92f5c7b2","sourceSectionSha256":"fc89233a40e0a3b0f07885207651344b5ccbcbee047670a6894bee2c111619d3","pdfPages":[75],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='21:core:france' and section_id=21 and place_id='france';
update public.place_references set category='action',scene_text='The boat excursion takes place off the Georgia coast; the island is only seen from the water. The state outline provides geographical context; it does not trace the boat trip or imply a landing.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"515a48a5a9a48f11a800f3f8421dc4aca4a32835bb1e3c0017ab7c6d5359b6ab","sectionId":"2.2","placeId":"georgia","category":"action","narrativeLevel":"recalled scene","reason":"La scena avviene sulla barca al largo della Georgia, non sull’isola vista a distanza.","viewerPage":103,"printedPage":102,"sourceImageSha256":"9c53258dea758a4cbfb02f5cd37d7303e28b404de2a001eade55733b946f939a","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[139],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:georgia' and section_id=36 and place_id='georgia';
update public.place_references set category='action',scene_text='At a Mississippi resort museum, Humbert discovers a photograph of the Hotel Mirana and Dolores answers him. The state is established, but the museum’s exact site is unresolved.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"fdef5e5f1f0e5f5a7bd2dba7223d627edccd3efa81460e7d0121b6db0a2c4020","sectionId":"2.2","placeId":"mississippi","category":"action","narrativeLevel":"recalled scene","reason":"La scoperta della fotografia del Mirana e la replica di Dolores sono eventi nel museo del Mississippi, il cui nome/località non sono identificati.","viewerPage":103,"printedPage":102,"sourceImageSha256":"9c53258dea758a4cbfb02f5cd37d7303e28b404de2a001eade55733b946f939a","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[139],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:mississippi' and section_id=36 and place_id='mississippi';
update public.place_references set category='action',scene_text='In an Arkansas forest, Humbert treats an insect bite on Dolores’s shoulder. The forest is unnamed; the outline represents the state, not a precise site.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"49bffd516c35e0faab51d372448fa9dc2448c0860ba3a5caa24d59396db26874","sectionId":"2.2","placeId":"arkansas","category":"action","narrativeLevel":"recalled scene","reason":"La puntura e il trattamento della spalla sono un episodio effettivo nel bosco, non la sola parola Arkansas in un elenco.","viewerPage":103,"printedPage":102,"sourceImageSha256":"9c53258dea758a4cbfb02f5cd37d7303e28b404de2a001eade55733b946f939a","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[139],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:arkansas' and section_id=36 and place_id='arkansas';
update public.place_references set category='action',scene_text='At Little Iceberg Lake, described only as somewhere in Colorado, Dolores slides on snow and exchanges snowballs with other youngsters. The outline shows the state, not an identified lake.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"f69d9c3e5139a89e9f5b6f44ef8317e87c260b4550452a17882f2bb5d255b0e8","sectionId":"2.2","placeId":"colorado","category":"action","narrativeLevel":"recalled scene","reason":"Il testo dice somewhere in Colorado; scivolata e battaglia di neve narrate provano action, non l’identità di un lago omonimo.","viewerPage":104,"printedPage":103,"sourceImageSha256":"94620498b44dccb11f31c84bda6d7fae8430dd07e68c66e1e06b57eccc5bf457","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[140],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:colorado' and section_id=36 and place_id='colorado';
update public.place_references set category='action',scene_text='The journey includes the observed episode of a man having a seizure in Russian Gulch State Park. This brief vignette narrates an event; the point represents the park, not the spot of the episode.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"840c9c57d0c5e9de85dcaf40dc70e2b88a82c5b75ee1577867ab1686ebc5dfab","sectionId":"2.2","placeId":"russian-gulch","category":"action","narrativeLevel":"recalled scene","reason":"Una vignetta nominale narra un evento osservato con attore e ambientazione espliciti; la lunghezza non ne annulla la funzione di scena.","viewerPage":104,"printedPage":103,"sourceImageSha256":"94620498b44dccb11f31c84bda6d7fae8430dd07e68c66e1e06b57eccc5bf457","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[141],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:russian-gulch' and section_id=36 and place_id='russian-gulch';
update public.place_references set category='action',scene_text='In California, Dolores takes tennis lessons: Humbert describes the coach returning a shot during a lesson. The state outline does not identify a court or club.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"5190f881807d65dc0c7d70956788dc83f278f9d97ee26a315ca419431d8a00c4","sectionId":"2.2","placeId":"california","category":"action","narrativeLevel":"recalled scene","reason":"La lezione descrive il gesto del maestro sul campo: azione abituale concretamente narrata, non sola notizia di iscrizione.","viewerPage":107,"printedPage":106,"sourceImageSha256":"dcfca1edd3194dbebf2a8ebcb46000e9022726a3b2bd31f2acfeca27809a2668","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[145],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:california' and section_id=36 and place_id='california';
update public.place_references set category='action',scene_text='At the Poplar Shade motel in Utah, Dolores questions their life in cabins. This is an enacted exchange within the travel montage; the motel has no verified real address.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"93b2b16d2640a6c09eed822bae160eb184bb575155dbb736c08f36714d511489","sectionId":"2.2","placeId":"utah","category":"action","narrativeLevel":"recalled scene","reason":"Il soggiorno al motel contiene la domanda di Dolores sulla vita insieme: scena narrata dentro il riepilogo dei litigi.","viewerPage":105,"printedPage":104,"sourceImageSha256":"e0ba15588f53ecfde575edb18701ab2f03b3b4c1491505e36552e314bace4233","sourceSectionSha256":"d388d4bdd0c0ffa859493075c17d5bfc0b17d8aab67dd23f798fceae58b35052","pdfPages":[141],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='36:core:utah' and section_id=36 and place_id='utah';
update public.place_references set category='action',scene_text='At Champion Hotel in Colorado, Dolores plays tennis before a telephone call interrupts Humbert. Champion remains fictional; the regional position identifies no hotel or court.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"f24e5f03dfaf27466deb3a2ebcb36f333434d810fd7cb99b03ad66e59acab528","sectionId":"2.20","placeId":"colorado","category":"action","narrativeLevel":"memoir scene","reason":"Lo Stato è esplicito nella scena di tennis; distinto dalla città fittizia e dalle precedenti lezioni californiane.","viewerPage":155,"printedPage":154,"sourceImageSha256":"4ce5070bc0b07247271b6d73af79550b216a3527b76da21234a4e01cfa45e39d","sourceSectionSha256":"195c1d08c77fe399579c69d6d895e886a2a0de7a4071b4815dfa3a8a3610f2f6","pdfPages":[213],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='54:core:colorado' and section_id=54 and place_id='colorado';
update public.place_references set category='action',scene_text='Humbert recalls a woman speaking to him at a tea in Paris. This remembered conversation makes Paris an action setting here; it is distinct from the present-day letter scene.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"06dbc1ccb5b7854e7f9bd5e25b2a8fcc4e2003c592d123515c55eae4422c0f6c","sectionId":"2.27","placeId":"paris","category":"action","narrativeLevel":"recalled scene","reason":"Dialogo ricordato con una donna durante un tè a Parigi, distinto dalla scena presente della posta.","viewerPage":176,"printedPage":175,"sourceImageSha256":"147340df58933ccc7a93531e28998393acbd0bab2d4f55d62b229fa8bafbb5f5","sourceSectionSha256":"676584351e988d2768eab220be30e04deb80ba6444d97d56143e62d155809cb3","pdfPages":[242],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='61:core:paris' and section_id=61 and place_id='paris';
update public.place_references set category='action',scene_text='In the afterword, Nabokov recalls reading the early Russian prototype to friends in wartime Paris. This is an autobiographical scene, separate from Humbert’s fictional journeys.',metadata=metadata||'{"explicitCategory":true,"narrativeReview":{"id":"50e5c2963e45e15e227bd8987a2b0dce1abc392fe657cc08cd94bf4a938ad353","sectionId":"afterword","placeId":"paris","category":"action","narrativeLevel":"authorial autobiography","reason":"Nabokov ricorda la lettura del prototipo agli amici a Parigi: scena autobiografica, non viaggio di Humbert né sola cronologia editoriale.","viewerPage":208,"printedPage":207,"sourceImageSha256":"c90fda62c56eefeec5b2300e86b4bdf3aeedc6789a26269aa00b9b0a9038397c","sourceSectionSha256":"e2669e65c5570edec01df17b88e95849665bb749333752eef19d238eaa8d0160","pdfPages":[],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb where book_id='lolita' and id='71:core:paris' and section_id=71 and place_id='paris';
