on conflict(book_id,language,source_hash) do update set translated_text=excluded.translated_text where public.content_translations.book_id='lolita';
do $scope$ begin if exists(select 1 from lolita_review_scope_guard original full join (select 'books'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.books r where r.id<>'lolita') rows
union all
select 'place_references'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.place_references r where r.book_id<>'lolita') rows
union all
select 'place_descriptions'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.place_descriptions r where r.book_id<>'lolita') rows
union all
select 'sources'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.sources r where r.book_id<>'lolita') rows
union all
select 'content_translations'::text as target,md5(coalesce(string_agg(h,'' order by h),'')) as digest from (select md5(to_jsonb(r)::text) h from public.content_translations r where r.book_id<>'lolita') rows) current_rows using(target) where original.digest is distinct from current_rows.digest) then raise exception 'Scope verification failed: another book was modified; transaction rolled back';end if;end $scope$;
