insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values('lolita','37:core:california',37,'california','core',4,'action','The chapter recalls an episode on a California beach. The state is explicit; the beach and its cave remain unidentified, so the map uses a state outline.','f8a12cd9eeb1325d8f7b9e1444884bcf84360887be6cff66bff4ac3f7a87ffd8','{"explicitCategory":true,"narrativeReview":{"id":"0f307b595116da25910fe6ce7c2f311c48343635a3b839b3bf0a1639d8073aaf","sectionId":"2.3","placeId":"california","category":"action","narrativeLevel":"recalled scene","reason":"L’episodio sulla spiaggia californiana è narrato, ma la spiaggia non ha nome; il Pacifico non viene promosso come scena distinta.","viewerPage":111,"printedPage":110,"sourceImageSha256":"2be788d491561723436ae576b33b76904ee3e236fb8dbd5288cfdf9db28e3a33","sourceSectionSha256":"843216895d5433783fd135eb9c894eff9393aafaa94a70702b001e09f0eafc7e","pdfPages":[150],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb) on conflict(book_id,id) do update set category=excluded.category,scene_text=excluded.scene_text,metadata=public.place_references.metadata||excluded.metadata where public.place_references.book_id='lolita' and public.place_references.section_id=excluded.section_id and public.place_references.place_id=excluded.place_id;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values('lolita','61:core:new-york',61,'new-york','core',6,'action','Humbert receives the letters from Farlow and Dolores at his New York flat. The city is established in the preceding chapter; no street number is given.','9a1dd3c23095f8b546683edaf8aee55fdd6f339e4ded5a0c2f17027ba7b81a81','{"explicitCategory":true,"narrativeReview":{"id":"11767ff099d38c21e0e841e0fade8b8f6e5c86044374c1413f3d58c39b601d16","sectionId":"2.27","placeId":"new-york","category":"action","narrativeLevel":"memoir scene","reason":"Ricezione e lettura della posta nell’appartamento: il contesto di New York/Central Park West è stabilito da II.26, senza inventare un numero civico.","viewerPage":176,"printedPage":175,"sourceImageSha256":"147340df58933ccc7a93531e28998393acbd0bab2d4f55d62b229fa8bafbb5f5","sourceSectionSha256":"676584351e988d2768eab220be30e04deb80ba6444d97d56143e62d155809cb3","pdfPages":[241],"pdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee","publicQuotationStatus":"pending-edition-and-individual-aggregate-rights-review"}}'::jsonb) on conflict(book_id,id) do update set category=excluded.category,scene_text=excluded.scene_text,metadata=public.place_references.metadata||excluded.metadata where public.place_references.book_id='lolita' and public.place_references.section_id=excluded.section_id and public.place_references.place_id=excluded.place_id;
