insert into public.content_translations(book_id,language,source_hash,source_text,translated_text) values
('lolita','en','40d4e7404b761537861d409715bf0e352a3bf837be5561575c0043032668026f','The childhood scenes are set on the Riviera near the fictional Hotel Mirana. The diamond indicates the Mediterranean coastal region; it does not identify the hotel, villa, school or beach, or choose a real town as their equivalent.','The childhood scenes are set on the Riviera near the fictional Hotel Mirana. The diamond indicates the Mediterranean coastal region; it does not identify the hotel, villa, school or beach, or choose a real town as their equivalent.'),
('lolita','it','40d4e7404b761537861d409715bf0e352a3bf837be5561575c0043032668026f','The childhood scenes are set on the Riviera near the fictional Hotel Mirana. The diamond indicates the Mediterranean coastal region; it does not identify the hotel, villa, school or beach, or choose a real town as their equivalent.','Le scene d’infanzia si svolgono sulla Riviera presso l’Hotel Mirana immaginario. Il rombo indica la regione costiera mediterranea; non identifica albergo, villa, scuola o spiaggia e non sceglie una città reale equivalente.'),
('lolita','fr','40d4e7404b761537861d409715bf0e352a3bf837be5561575c0043032668026f','The childhood scenes are set on the Riviera near the fictional Hotel Mirana. The diamond indicates the Mediterranean coastal region; it does not identify the hotel, villa, school or beach, or choose a real town as their equivalent.','Les scènes d’enfance se déroulent sur la Riviera près de l’hôtel Mirana fictif. Le losange indique la région côtière méditerranéenne ; il n’identifie ni hôtel, ni villa, ni école, ni plage et ne choisit pas de ville réelle équivalente.'),
('lolita','es','40d4e7404b761537861d409715bf0e352a3bf837be5561575c0043032668026f','The childhood scenes are set on the Riviera near the fictional Hotel Mirana. The diamond indicates the Mediterranean coastal region; it does not identify the hotel, villa, school or beach, or choose a real town as their equivalent.','Las escenas de infancia transcurren en la Riviera cerca del Hotel Mirana ficticio. El rombo indica la región costera mediterránea; no identifica hotel, villa, escuela ni playa, ni elige una ciudad real equivalente.'),
('lolita','en','ce482c0326fa576d76628d0452ebdf0bf0d8f1d63fa0f36a3f8658d093a3a1c6','Only the geographical region is established. This rounded point is selected within it for orientation; it is not a scene, address, route reconstruction or probability estimate.','Only the geographical region is established. This rounded point is selected within it for orientation; it is not a scene, address, route reconstruction or probability estimate.'),
('lolita','it','ce482c0326fa576d76628d0452ebdf0bf0d8f1d63fa0f36a3f8658d093a3a1c6','Only the geographical region is established. This rounded point is selected within it for orientation; it is not a scene, address, route reconstruction or probability estimate.','È stabilita soltanto la regione geografica. Il punto arrotondato è scelto al suo interno per orientarsi; non è una scena, un indirizzo, una ricostruzione del percorso o una stima di probabilità.'),
('lolita','fr','ce482c0326fa576d76628d0452ebdf0bf0d8f1d63fa0f36a3f8658d093a3a1c6','Only the geographical region is established. This rounded point is selected within it for orientation; it is not a scene, address, route reconstruction or probability estimate.','Seule la région géographique est établie. Ce point arrondi est choisi à l’intérieur pour s’orienter ; ce n’est ni une scène, ni une adresse, ni un trajet reconstitué, ni une estimation de probabilité.'),
('lolita','es','ce482c0326fa576d76628d0452ebdf0bf0d8f1d63fa0f36a3f8658d093a3a1c6','Only the geographical region is established. This rounded point is selected within it for orientation; it is not a scene, address, route reconstruction or probability estimate.','Solo queda establecida la región geográfica. El punto redondeado se elige dentro de ella para orientarse; no es una escena, una dirección, un recorrido reconstruido ni una estimación de probabilidad.'),
